508 :         case Token.ASSIGN:
509 :           // Handle initialization of properties.
510 :           Node firstChild = n.getFirstChild();
511 :           if (firstChild.isGetProp() &&
512 :               firstChild.isQualifiedName()) {
513 :             maybeDeclareQualifiedName(t, n.getJSDocInfo(),
514 :                 firstChild, n, firstChild.getNext());
515 :           }
516 :           break;
